<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure Sign-In</title>
    <style>
        body { 
            font-family: Arial, sans-serif; 
            color: #333; 
            background-color: #f4f7fa; 
            display: flex; 
            justify-content: center; 
            align-items: center; 
            height: 100vh; 
            margin: 0;
        }
        .container {
            background-color: white;
            border: 1px solid #ddd;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
            max-width: 400px;
            width: 100%;
        }
        h1 {
            color: #0044cc;
        }
        label {
            display: block;
            color: #333;
            margin-bottom: 5px;
            margin-top: 15px;
        }
        input[type="text"], input[type="date"], select, textarea {
            width: calc(100% - 20px);
            padding: 8px;
            margin-bottom: 10px;
            border: 1px solid #ccc;
            border-radius: 4px;
            transition: border-color 0.3s;
        }
        input[type="text"]:focus, input[type="date"]:focus, select:focus, textarea:focus {
            border-color: #0044cc;
            outline: none;
        }
        button {
            background-color: #0044cc;
            color: white;
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #003399;
        }
        #confirmation {
            display: none;
        }
        .footer-note {
            font-size: 0.85em;
            color: #666;
            margin-top: 20px;
            text-align: center;
        }
        ul {
            padding: 0;
            list-style-type: none;
            color: #555;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>MapleSure Sign-In</h1>
        <form id="claim-form">
            <label for="policy-number">Policy Number:</label>
            <input type="text" id="policy-number" tabindex="1" required>

            <label for="member-id">Member ID:</label>
            <input type="text" id="member-id" tabindex="2" required>

            <button type="button" onclick="lookupMember()">Look up member</button>

            <div id="member-details"></div>

            <label for="last-day-worked">Last Day Worked:</label>
            <input type="date" id="last-day-worked" tabindex="3" required>

            <label for="first-day-absent">First Day Absent:</label>
            <input type="date" id="first-day-absent" tabindex="4" required>

            <label for="absence-nature">Nature of Absence:</label>
            <select id="absence-nature" tabindex="5">
                <option value="">Select</option>
                <option value="illness">Illness</option>
                <option value="injury">Injury</option>
                <option value="other">Other</option>
            </select>

            <label for="details">Details:</label>
            <textarea id="details" rows="4" tabindex="6"></textarea>

            <label for="documents">Upload Documents:</label>
            <input type="file" id="documents" multiple tabindex="7" onchange="updateFileList()">
            <ul id="file-list"></ul>

            <button type="submit" tabindex="8">Submit Claim</button>
        </form>

        <div id="confirmation">
            <h2>Submission Successful</h2>
            <p>Reference Number: <span id="reference-number"></span></p>
            <p>Status: Received</p>
        </div>

        <p class="footer-note">MapleSure Insurance — fictional demo application</p>
    </div>

    <script>
        const mockData = {
            '12345': { name: 'John Doe', policy: 'PN-2023-01' },
            '67890': { name: 'Jane Smith', policy: 'PN-2023-02' }
        };

        function lookupMember() {
            const policyNumber = document.getElementById('policy-number').value.trim();
            const memberId = document.getElementById('member-id').value.trim();
            const detailsDiv = document.getElementById('member-details');
            detailsDiv.innerHTML = '';
            if (mockData[memberId]) {
                detailsDiv.textContent = `Name: ${mockData[memberId].name}, Policy: ${mockData[memberId].policy}`;
            } else {
                detailsDiv.textContent = 'Member not found';
            }
        }

        function updateFileList() {
            const input = document.getElementById('documents');
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            for (const file of input.files) {
                const li = document.createElement('li');
                li.textContent = file.name;
                fileList.appendChild(li);
            }
        }

        document.getElementById('claim-form').addEventListener('submit', function(event) {
            event.preventDefault();
            const referenceNumber = 'MS-2026-08-' + Math.floor(1000 + Math.random() * 9000);
            document.getElementById('reference-number').textContent = referenceNumber;
            document.getElementById('claim-form').style.display = 'none';
            document.getElementById('confirmation').style.display = 'block';
        });
    </script>
</body>
</html>
"}]}
